# 定义一个资源类，用于自动校验views视图的入参和返回值校验
class Resource(ViewSet, metaclass=abc.ABCMeta):
 # 定义一个资源类，用于自动校验views视图的入参和返回值校验
 RequestSerializer = None
 ResponseSerializer = None
